    ('GOTAS DE AMOR 2024', 'GOTAS_DE_AMOR', 'OD00761608', 60.0::numeric, NULL::text, '{"estado": "MONAGAS", "municipio": "MATURIN", "parroquia": "SAN SIMON", "cod_plantel": "OD00761608", "CRUCE": "EXISTE", "ABORDAJE": "CON ABORDAJE", "GRUPO_TAREA": "INSPECCION", "ENTE ENCARGADO": "", "CHECK ATENCION": "", "AÑO": "", "TIPO ATENCION": "", "RESPONSABLE": "JENNIFER VILLAHERMOSA", "FOTOS": "SI", "INFORME": "SI", "DESGLOSE_XLS": "SI", "DESGLOSE_PDF": "NO", "CROQUIS": "SI", "FICHA": "NO", "MESA SILLA": "", "COCINA": "", "MOBILIARIO": "", "KIT JARDIN": "", "KIT DEP": "", "nombre_plantel": "CENTRO DE EDUCACION INICIAL EL LIBERTADOR", "tipo_dependencia": "Nacional", "denominacion": "CENTRO DE EDUCACION INICIAL", "CANT_AULAS": "", "estatus_plantel": "ACTIVO", "modalidad_principal": "SISTEMA REGULAR", "nivel_principal": "EDUCACIÃ“N INICIAL", "zona_ubucacion": "Urbana", "director_nombre": "LEIDY MARY", "tipo_documento": "V", "documento_identidad": "15633109", "telefono_director": "", "telefono_movil_director": "4267956175", "correo": "lmmarquez27@gmail.com", "twitter": "", "total_maternal": "15", "total_preescolar": "67", "total_primaria": "0", "total_media": "0", "total_media_general": "0", "total_tecnica": "0", "total_adulto": "0", "total_mr": "0", "total_ribas_tecnica": "0", "total_especial": "0", "total_matrÃ­cula_registrada": "82", "direccion": "CARRERA 2 CALLE 29 ", "COD_CIRCUITO": "C-URB-2018-11-0062", "NOMB_CIRCUITO": "LOS CHAIMAS DE SAN SIMÓN ", "COD_CONSEJO_COM": "U-CCO-14-07-10-024704", "NOM_CONSEJO_COM": "CALLE 28A SECTOR ALBERTO RABELL", "PLAN PRE 2026-2027": ""}'::jsonb)
  ) AS t(plan, tipo, cod, avance, rehab, membrete)
  LOOP
    INSERT INTO planes_atencion (nombre, descripcion, version_catalogo, tipo)
    VALUES (r.plan, 'Plan histórico cargado desde los archivos de 2024', 'LISTA2', r.tipo)
    ON CONFLICT (nombre) DO NOTHING;
    SELECT id INTO v_plan FROM planes_atencion WHERE nombre = r.plan;

    IF EXISTS (SELECT 1 FROM plan_inspecciones WHERE plan_id = v_plan AND codigo_dea = r.cod) THEN
      v_existentes := v_existentes + 1;
    ELSE
      INSERT INTO inspecciones (codigo_dea, membrete, origen, estado)
      VALUES (r.cod, r.membrete, 'HISTORICA', 'BORRADOR')
      RETURNING id INTO v_insp;
      INSERT INTO plan_inspecciones (plan_id, inspeccion_id, codigo_dea, ejecucion, ingeniero_rehab, avance_historico)
      VALUES (v_plan, v_insp, r.cod, 'CERRADO', r.rehab, r.avance);
      v_nuevos := v_nuevos + 1;
    END IF;
  END LOOP;
  RAISE NOTICE 'Planteles cargados: %, ya existían: %', v_nuevos, v_existentes;
END
$$;
